script:
data = frappe.request.get_json() or {}
search = (data.get("search") or "").strip()
limit = int(data.get("limit") or 200)
if limit > 500: limit = 500

try:
    # Varieties are Items in the "Roses" / variety item-group. We can't know
    # the exact group on every instance, so filter by item_group containing
    # "Variet" or "Rose", then fall back to a search-only result.
    filters = {"disabled": 0}
    if search:
        # SQL LIKE search on item_name
        filters["item_name"] = ["like", "%" + search + "%"]

    rows = frappe.get_all(
        "Item",
        filters=filters,
        fields=["name", "item_name", "item_group"],
        order_by="item_name asc",
        limit=limit * 4,
    )

    out = []
    for r in rows:
        grp = (r.get("item_group") or "").lower()
        # Heuristic: keep Items whose group looks variety/rose-related.
        if "variet" in grp or "rose" in grp or grp == "":
            out.append({
                "name": r.get("name") or "",
                "label": r.get("item_name") or r.get("name") or "",
                "item_group": r.get("item_group") or "",
            })
        if len(out) >= limit:
            break

    frappe.response["data"] = {"count": len(out), "varieties": out}
except Exception as e:
    frappe.log_error("productionListVarieties error: " + str(e))
    frappe.response["data"] = {"error": str(e)}
